import { handleTelegramRequest, isUserBlocked, readAdminSetting } from './admin.js';
const EMBEDDED_APP_JS = "const API_BASE = '';\nconst NEWS_URL = '';\nconst CHAT_URL = '';\nconst tg = window.Telegram?.WebApp;\nfunction syncTelegramViewport(){\n  if(!tg) return;\n  try { tg.expand(); tg.setHeaderColor?.('#06101d'); tg.setBackgroundColor?.('#06101d'); } catch(e) {}\n  document.documentElement.style.setProperty('--tg-viewport-height', ((tg.viewportHeight || window.innerHeight) + 'px'));\n  document.documentElement.style.setProperty('--tg-stable-viewport-height', ((tg.viewportStableHeight || tg.viewportHeight || window.innerHeight) + 'px'));\n}\nconst state = { user:null, config:null, ready:false, busy:false, activePage:'mine', adController:null, demo:false }; let regenTimer=null;\nconst $ = id => document.getElementById(id);\nconst fmt = n => Math.max(0,Number(n)||0).toLocaleString('en-US');\nfunction toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}\nfunction showPage(name){syncTelegramViewport();window.scrollTo(0,0);document.scrollingElement?.scrollTo(0,0);state.activePage=name;document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===`page-${name}`));document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===name));if(name==='leaderboard'){if(state.rankMode)renderRankPage();else loadLeaderboard();}if(name==='squad')renderReferrals();if(name==='daily')renderDailyPage();}\nasync function api(path,body){const res=await fetch(`${API_BASE}/api${path}`,{method:body?'POST':'GET',headers:body?{'content-type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await res.json().catch(()=>({error:'Invalid server response'}));if(!res.ok)throw new Error(data.error||`Request failed (${res.status})`);return data}\nfunction hideLoader(){ $('loadingScreen').classList.add('hidden');setTimeout(()=>$('loadingScreen').remove(),300); }\nfunction updateRegenTimer(){clearInterval(regenTimer);const el=$('regenText');if(!el||!state.user)return;const at=Number(state.user.nextEnergyAt||0);const energy=Number(state.user.energy||0);const max=Number(state.user.maxEnergy||0);if(energy>0||!at){el.textContent=energy>=max?'FULL':'READY';return;}const tick=()=>{const sec=Math.max(0,Math.ceil((at-Date.now())/1000));if(sec<=0){el.textContent='READY';clearInterval(regenTimer);setTimeout(()=>boot(),500);return;}const hh=String(Math.floor(sec/3600)).padStart(2,'0');const mm=String(Math.floor((sec%3600)/60)).padStart(2,'0');const ss=String(sec%60).padStart(2,'0');el.textContent=hh+':'+mm+':'+ss};tick();regenTimer=setInterval(tick,1000)}\nfunction renderTaskState(){const s=state.user?.taskStatus||{};document.querySelectorAll('[data-claim-task]').forEach(b=>{const claimed=!!s[b.dataset.claimTask];b.disabled=claimed;b.textContent=claimed?'Claimed':'Claim';b.classList.toggle('claimed',claimed);});}\nfunction updateUI(){const u=state.user;if(!u)return;$('balance').textContent=fmt(u.points);$('boostBalance').textContent=fmt(u.points);$('taskBalance').textContent=fmt(u.points);$('energyText').textContent=`${Math.floor(u.energy)} / ${u.maxEnergy}`;$('profileEnergy').textContent=`${Math.floor(u.energy)} / ${u.maxEnergy}`;$('energyFill').style.width=`${Math.max(0,Math.min(100,u.energy/u.maxEnergy*100))}%`;$('tapPower').textContent=`+${u.tapPower}`;$('streak').textContent=`${u.streak||0} days`;$('rank').textContent=u.rank||'Rookie';$('username').textContent=u.firstName||'Miner';$('avatar').textContent=(u.firstName||'N').slice(0,1).toUpperCase();$('profileAvatar').textContent=(u.firstName||'N').slice(0,1).toUpperCase();$('profileName').textContent=u.firstName||'Nexus Miner';$('telegramId').textContent=u.telegramId?`Telegram ID · ${u.telegramId}`:'Preview mode';$('profilePoints').textContent=fmt(u.points);$('profileReferrals').textContent=fmt(u.referralCount||0);$('profileRank').textContent=u.rank||'Rookie';$('profileStreak').textContent=fmt(u.streak||0);$('profileEnergy').textContent=`${Math.floor(u.energy)} / ${u.maxEnergy}`;$('profileUsername').textContent=u.username?`@${u.username}`:'No username';$('refCount').textContent=fmt(u.referralCount||0);$('refTotal').textContent=`${fmt(u.referralCount||0)} invited`;$('profileLevel').textContent=(u.upgrades?.multitap||0)+(u.upgrades?.energy||0)+(u.upgrades?.recharge||0);$('multiLevel').textContent=u.upgrades?.multitap||0;$('energyLevel').textContent=u.upgrades?.energy||0;$('rechargeLevel').textContent=u.upgrades?.recharge||0;$('multiCost').textContent=fmt(u.upgradeCosts?.multitap||100);$('energyCost').textContent=fmt(u.upgradeCosts?.energy||150);$('rechargeCost').textContent=fmt(u.upgradeCosts?.recharge||125);renderTaskState();updateRegenTimer();}\nfunction demoUser(){return {telegramId:null,firstName:'NexusMiner',username:'',energyCost:10,points:12450,energy:780,maxEnergy:1000,tapPower:1,streak:3,rank:rankFromPoints(12450),referralCount:2,upgrades:{multitap:0,energy:0,recharge:0},upgradeCosts:{multitap:100,energy:150,recharge:125},referrals:[],nextEnergyAt:Date.now()+3600000}}\nasync function boot(){try{if(tg){tg.ready();syncTelegramViewport();tg.onEvent?.('viewportChanged',syncTelegramViewport);tg.onEvent?.('themeChanged',syncTelegramViewport);}window.addEventListener('resize',syncTelegramViewport,{passive:true});window.visualViewport?.addEventListener('resize',syncTelegramViewport,{passive:true});const initData=tg?.initData||'';syncTelegramViewport();if(!initData){state.demo=true;state.user=demoUser();toast('Preview mode — open from your Telegram bot to mine for real.');hideLoader();updateUI();return;}const data=await api('/session',{initData,startParam:String(tg?.initDataUnsafe?.start_param||'')});state.user=data.user;state.user.energyCost=Number(state.user.energyCost||10);state.config=data.config||{};const adminNav=document.querySelector('.admin-nav');if(adminNav)adminNav.style.display=state.config.isAdmin?'flex':'none';const ownerAdminWrap=document.getElementById('ownerAdminWrap');if(ownerAdminWrap)ownerAdminWrap.style.display=state.config.isAdmin?'block':'none';if(state.config.adsgramBlockId){initAds(state.config.adsgramBlockId);$('adRewardLabel').textContent=state.config.adRewardEnabled?'+25 NXG PTS · max 1000/day':'Ads active · reward pending publisher setup'}hideLoader();updateUI();}catch(err){hideLoader();state.demo=true;state.user=demoUser();updateUI();toast(`Preview mode: ${err.message}`)}}\nfunction initAds(blockId){if(!window.Adsgram||!blockId)return;try{state.adController=window.Adsgram.init({blockId:String(blockId)});$('adRewardLabel').textContent='Reward after full ad completion';}catch(e){console.warn('Adsgram init failed',e)}}\nfunction floatPoint(event,amount){const el=document.createElement('span');el.className='float-point';el.textContent=`+${amount}`;const rect=$('balance').getBoundingClientRect();el.style.left=`${rect.left+rect.width*.5+Math.random()*46-23}px`;el.style.top=`${rect.top+rect.height*.5+Math.random()*18-9}px`;el.style.transform='translate(-50%,-50%)';$('floatLayer').appendChild(el);setTimeout(()=>el.remove(),750)}\nlet tapQueue=0,tapTimer=null,tapSending=false;\nfunction tapMine(event){\n if(!state.user)return;\n if(state.demo){const cost=Number(state.user.energyCost||10);if(state.user.energy<cost)return toast('Not enough energy');state.user.energy-=cost;state.user.points+=state.user.tapPower;updateUI();floatPoint(event,state.user.tapPower);return;}\n if(state.user.energy<10)return toast('Not enough energy');\n state.user.energy=Math.max(0,state.user.energy-10);state.user.points+=state.user.tapPower;updateUI();floatPoint(event,state.user.tapPower);\n tapQueue++;\n if(!tapTimer)tapTimer=setTimeout(flushTaps,100);\n}\nasync function flushTaps(){\n tapTimer=null;if(tapSending||tapQueue<=0)return;\n tapSending=true;const count=Math.min(tapQueue,20);tapQueue-=count;\n try{const result=await api('/tap-batch',{initData:tg.initData,count});state.user=result.user;updateUI();}\n catch(e){state.user.energy=Math.min(state.user.maxEnergy,state.user.energy+count*Number(state.user.energyCost||10));state.user.points=Math.max(0,state.user.points-count*state.user.tapPower);updateUI();toast(e.message);}\n finally{tapSending=false;if(tapQueue>0)tapTimer=setTimeout(flushTaps,50);}\n}\nasync function upgrade(kind){if(state.demo){const cost=state.user.upgradeCosts[kind];if(state.user.points<cost)return toast('Not enough points');state.user.points-=cost;state.user.upgrades[kind]++;state.user.upgradeCosts[kind]=Math.ceil(cost*1.65);if(kind==='multitap')state.user.tapPower++;if(kind==='energy'){state.user.maxEnergy+=250;state.user.energy=state.user.maxEnergy}updateUI();return toast('Upgrade applied in preview');}try{const r=await api('/upgrade',{initData:tg.initData,kind});state.user=r.user;updateUI();toast('Upgrade successful');}catch(e){toast(e.message)}}\nconst streakRewards=[50,75,100,150,200,300,500];\nlet dailyTimer=null;\nfunction formatCountdown(ms){const sec=Math.max(0,Math.ceil(ms/1000));const h=String(Math.floor(sec/3600)).padStart(2,'0');const m=String(Math.floor((sec%3600)/60)).padStart(2,'0');const s=String(sec%60).padStart(2,'0');return h+':'+m+':'+s}\nfunction updateDailyCountdown(){clearInterval(dailyTimer);const u=state.user;if(!u)return;const tick=()=>{const at=Number(u.nextDailyAt||0);const el=$('dailyNextText');const btn=$('dailyPageClaim');const stateEl=$('dailyState');const label=$('dailyClaimLabel');if(at&&Date.now()<at){const left=at-Date.now();if(el)el.textContent='Next check-in available in '+formatCountdown(left);if(stateEl)stateEl.textContent='LOCKED';if(label)label.textContent='WAIT '+formatCountdown(left);if(btn){btn.disabled=true;btn.style.opacity='.55';}}else{if(el)el.textContent='24-hour window complete. Check in now to claim your NXG reward.';if(stateEl)stateEl.textContent='READY';if(label)label.textContent='CHECK IN';if(btn){btn.disabled=false;btn.style.opacity='1';}clearInterval(dailyTimer)}};tick();dailyTimer=setInterval(tick,1000)}\nfunction renderDailyPage(){const u=state.user;if(!u)return;const streak=Math.max(0,Number(u.streak||0));const nextDay=Math.max(1,Math.min(7,(streak%7)+1));const rewards=streakRewards;const reward=rewards[nextDay-1];$('dailyPageStreak').textContent=String(streak);$('dailyStreakValue').textContent=String(streak);$('dailyRewardValue').textContent=`+${reward} NXG`;$('dailyNextReward').textContent=`+${reward} NXG`;const box=$('dailyPageDays');if(box)box.innerHTML=rewards.map((r,i)=>`<div class=\"streak-day ${i+1===nextDay?'current':''} ${i+1<nextDay?'done':''}\"><span>DAY ${i+1}</span><b>+${r} NXG</b></div>`).join('');updateDailyCountdown()}\nasync function claimDailyFromPage(){await dailyClaim();renderDailyPage();}\nasync function dailyClaim(){if(state.demo){const now=Date.now();if(state.user.nextDailyAt&&now<state.user.nextDailyAt)return toast('Next daily check-in in '+formatCountdown(state.user.nextDailyAt-now));const day=Math.max(1,Math.min(7,((Number(state.user.streak||0)%7)+1)));const reward=streakRewards[day-1];state.user.points+=reward;state.user.streak++;state.user.nextDailyAt=now+86400000;updateUI();renderDailyPage();return toast('Daily reward claimed! +'+reward+' NXG Points');}try{const r=await api('/daily',{initData:tg.initData});state.user=r.user;updateUI();renderDailyPage();toast('Daily reward claimed! +'+(r.reward||50)+' NXG Points');}catch(e){toast(e.message)}}\nfunction inviteLink(){const id=state.user?.telegramId;if(!id)return '';return `https://t.me/Nexusgram_official_bot?startapp=${id}`}\nfunction shareInvite(){const link=inviteLink();if(!link)return toast('Referral link will be available after bot setup');if(tg?.openTelegramLink){tg.openTelegramLink(`https://t.me/share/url?url=${encodeURIComponent(link)}&text=${encodeURIComponent('Join me on NexusGram and start collecting NXG Points!')}`)}else if(navigator.share){navigator.share({title:'Join NexusGram',text:'Join me on NexusGram and start collecting NXG Points!',url:link}).catch(()=>{})}else{navigator.clipboard?.writeText(link);toast('Invite link copied')}}\nasync function copyInvite(){const link=inviteLink();if(!link)return toast('Referral link will be available after bot setup');try{await navigator.clipboard.writeText(link);toast('Invite link copied')}catch{toast(link)}}\nasync function renderReferrals(){if(state.demo){$('refList').innerHTML='<div class=\"empty-state\">Preview: referral list will appear here after launch.</div>';return;}try{const r=await api('/referrals?initData='+encodeURIComponent(tg.initData));$('refList').innerHTML=r.referrals.length?r.referrals.map(x=>`<div class=\"settings-row\"><span>${escapeHtml(x.firstName||'Nexus Miner')}</span><b>${x.active?'Active':'Joined'}</b></div>`).join(''):'<div class=\"empty-state\">Your squad is waiting. Invite your first friend!</div>';}catch(e){$('refList').innerHTML='<div class=\"empty-state\">Could not load squad.</div>'}}\nasync function loadLeaderboard(){if(state.demo){$('leaderList').innerHTML='<div class=\"empty-state\">Leaderboard is available after Telegram sign-in.</div>';return;}try{const r=await api('/leaderboard?initData='+encodeURIComponent(tg.initData));$('leaderList').innerHTML=r.rows.map((x,i)=>{const medal='<span class=\"leader-number\">#'+(i+1)+'</span>';return '<div class=\"leader-row\"><div class=\"leader-rank\">'+medal+'</div><div class=\"leader-avatar\">'+escapeHtml((x.firstName||'N').slice(0,1).toUpperCase())+'</div><div class=\"leader-name\"><b>'+escapeHtml(x.firstName||'Nexus Miner')+'</b><small>Rank '+(i+1)+'</small></div><div class=\"leader-points\">'+fmt(x.points)+' pts</div></div>'}).join('')||'<div class=\"empty-state\">Be the first miner on the leaderboard.</div>'}catch(e){toast(e.message)}}\nconst rankTiers=[{name:'Rookie',min:0},{name:'Bronze',min:1000},{name:'Silver',min:5000},{name:'Gold',min:15000},{name:'Platinum',min:35000},{name:'Diamond',min:75000},{name:'Master',min:150000},{name:'Grandmaster',min:300000}];\nfunction renderRankPage(){const u=state.user||{points:0};let i=0;for(let n=0;n<rankTiers.length;n++){if(Number(u.points||0)>=rankTiers[n].min)i=n;else break;}const cur=rankTiers[i],next=rankTiers[i+1]||null,need=next?Math.max(0,next.min-Number(u.points||0)):0;const page=document.getElementById('page-leaderboard');if(!page)return;const h=page.querySelector('h1');if(h)h.textContent='Rank';const e=page.querySelector('.eyebrow');if(e)e.textContent='PROGRESSION';const box=document.getElementById('leaderList');if(!box)return;const icon='<span class=\"rank-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2l8 4v6c0 5-3.5 8.5-8 10-4.5-1.5-8-5-8-10V6l8-4z\"/></svg></span>';const summary='<div class=\"rank-summary\"><div class=\"rank-summary-top\"><div>'+icon+'<div><small>CURRENT RANK</small><h2>'+cur.name+'</h2></div></div><div class=\"rank-summary-status\">CURRENT</div></div><div class=\"rank-progress\"><div class=\"rank-progress-bar\"><span style=\"width:'+(next?Math.min(100,(Number(u.points||0)-cur.min)/Math.max(1,next.min-cur.min)*100):100)+'%\"></span></div><div class=\"rank-progress-meta\"><span>'+fmt(u.points)+' NXG</span><span>'+(next?fmt(next.min)+' NXG':'MAX RANK')+'</span></div></div><div class=\"rank-next\">'+(next?'<b>'+fmt(need)+' NXG</b><span>needed for '+next.name+'</span>':'<b>MAX RANK</b><span>You reached the highest tier</span>')+'</div></div>';const rows=rankTiers.map(t=>{const unlocked=t.min<=Number(u.points||0);const current=t.name===cur.name;const status=current?'CURRENT':unlocked?'UNLOCKED':'LOCKED';return '<div class=\"rank-tier '+(current?'is-current ':'')+(unlocked?'is-unlocked':'is-locked')+'\"><div class=\"rank-tier-icon\">'+icon+'</div><div class=\"rank-tier-main\"><b>'+t.name+'</b><small>Requirement · '+fmt(t.min)+' NXG</small></div><div class=\"rank-tier-status '+(current?'current':unlocked?'unlocked':'locked')+'\">'+status+'</div></div>'}).join('');box.innerHTML=summary+'<div class=\"rank-list-title\">RANK TIERS</div>'+rows;}\nconst taskStartedAt={};\nasync function openTask(which){\n const url=which==='news'?(state.config?.newsUrl||NEWS_URL||'https://t.me/nexusgram_official'):which==='youtube'?(state.config?.youtubeUrl||'https://youtube.com/@rajtilakeditz?si=OLEQqNUEq8H4240c'):(state.config?.chatUrl||CHAT_URL||'https://t.me/teslaspacex_roadster');\n if(!url)return toast('This official link is not configured yet');\n if(url.startsWith('https://t.me/')&&tg?.openTelegramLink)tg.openTelegramLink(url);else window.open(url,'_blank','noopener');\n if(which==='news'){toast('Join the channel, then tap Claim reward.');return;}\n if(which==='youtube'){taskStartedAt.youtube=Date.now();toast('Watch for at least 5 seconds, then tap Claim reward.');}\n}\nasync function watchAd(){if(!state.adController)return toast('Adsgram is not configured yet. Add your approved block ID.');toast('Loading Adsgram…');try{const result=await state.adController.show();if(result?.done){if(!state.config?.adRewardEnabled)return toast('Ad completed. Rewards are not enabled for this publisher yet.');const claim=await api('/ad-reward',{initData:tg.initData,claimId:crypto.randomUUID()});state.user=claim.user;updateUI();toast(`Ad completed! +${claim.reward} NXG Points`);}else toast('Ad not completed — no reward.')}catch(e){toast('Ad skipped or unavailable — no reward.')} }\nfunction escapeHtml(s){return String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]))}\ndocument.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{state.rankMode=false;showPage(b.dataset.page)}));\ndocument.querySelectorAll('[data-stat-go]').forEach(b=>{b.addEventListener('click',()=>{state.rankMode=true;showPage(b.dataset.statGo)});b.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')state.rankMode=true,showPage(b.dataset.statGo)});});document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.go)));$('tapButton').addEventListener('click',tapMine);document.querySelectorAll('[data-upgrade]').forEach(b=>b.addEventListener('click',()=>upgrade(b.dataset.upgrade)));$('dailyPageClaim')?.addEventListener('click',claimDailyFromPage);$('shareButton').addEventListener('click',shareInvite);$('copyButton').addEventListener('click',copyInvite);$('watchAdButton').addEventListener('click',watchAd);\ndocument.querySelectorAll('[data-task]').forEach(b=>b.addEventListener('click',()=>openTask(b.dataset.task)));\nasync function claimTask(which){\n if(state.demo)return toast('Open the app from Telegram to claim rewards');\n try{const r=await api('/task-reward',{initData:tg.initData,task:which,startedAt:taskStartedAt[which]||0});state.user=r.user;updateUI();toast('Task reward claimed! +'+r.reward+' NXG Points');const btn=document.querySelector('[data-claim-task=\"'+which+'\"]');if(btn){btn.disabled=true;btn.textContent='Claimed';}}catch(e){toast(e.message)}\n}\ndocument.querySelectorAll('[data-claim-task]').forEach(b=>b.addEventListener('click',()=>claimTask(b.dataset.claimTask)));\nasync function redeemCode(){if(state.demo)return toast('Open NexusGram from Telegram to redeem');const input=$('redeemCodeInput');const code=String(input?.value||'').trim();if(!code)return toast('Enter the redeem code');try{const r=await api('/redeem',{initData:tg.initData,code});state.user=r.user;updateUI();if(input)input.value='';toast('Redeemed successfully! +'+r.reward+' NXG Points');}catch(e){toast(e.message)}}\nasync function openAdmin(){if(!state.config?.isAdmin)return;const r=await api('/admin/settings',{initData:tg.initData});for(const [k,v] of Object.entries(r.settings)){const el=document.getElementById('adm'+({tap_reward:'TapReward',energy_cost:'EnergyCost',daily_bonus:'DailyBonus',referral_bonus:'ReferralBonus',ad_reward:'AdReward',redeem_code:'RedeemCode',redeem_reward:'RedeemReward',multitap_base_cost:'MultiCost',energy_base_cost:'EnergyCostBase',recharge_base_cost:'RechargeCost',news_url:'NewsUrl',chat_url:'ChatUrl',youtube_url:'YoutubeUrl'}[k]||''));if(el)el.value=v;}setAdminSwitch('mining_enabled',r.settings.mining_enabled);setAdminSwitch('ads_enabled',r.settings.ads_enabled);setAdminSwitch('maintenance_mode',r.settings.maintenance_mode);showPage('admin');}\nfunction setAdminSwitch(k,v){const b=document.querySelector('[data-admin-toggle=\"'+k+'\"]');if(b){b.dataset.value=String(v);const out=b.querySelector('b');if(out)out.textContent=String(v)==='1'?'ON':'OFF';}}\n$('profileButton')?.addEventListener('click',()=>showPage('profile'));$('ownerAdminButton')?.addEventListener('click',openAdmin);document.querySelector('.admin-nav')?.addEventListener('click',openAdmin);$('openRedeemButton')?.addEventListener('click',()=>{const box=$('redeemBox');if(box)box.classList.toggle('open');$('redeemCodeInput')?.focus();});$('redeemClaimButton')?.addEventListener('click',redeemCode);$('redeemCodeInput')?.addEventListener('keydown',e=>{if(e.key==='Enter')redeemCode();});document.querySelectorAll('[data-admin-toggle]').forEach(b=>b.addEventListener('click',()=>setAdminSwitch(b.dataset.adminToggle,b.dataset.value==='1'?'0':'1')));\n$('adminSave')?.addEventListener('click',async()=>{try{const map={tap_reward:'admTapReward',energy_cost:'admEnergyCost',daily_bonus:'admDailyBonus',referral_bonus:'admReferralBonus',ad_reward:'admAdReward',telegram_task_reward:'admTelegramTaskReward',youtube_task_reward:'admYoutubeTaskReward',redeem_code:'admRedeemCode',redeem_reward:'admRedeemReward',multitap_base_cost:'admMultiCost',energy_base_cost:'admEnergyCostBase',recharge_base_cost:'admRechargeCost',news_url:'admNewsUrl',chat_url:'admChatUrl',youtube_url:'admYoutubeUrl'};for(const [k,id] of Object.entries(map))await api('/admin/set',{initData:tg.initData,key:k,value:$(id).value});for(const k of ['mining_enabled','ads_enabled','maintenance_mode'])await api('/admin/set',{initData:tg.initData,key:k,value:document.querySelector('[data-admin-toggle=\"'+k+'\"]').dataset.value||'0'});toast('Admin settings saved');}catch(e){toast(e.message)}});$('profileButton').addEventListener('click',()=>showPage('profile'));\nboot();\n"

