function energyState(row,now){const max=Number(row.max_energy||START_ENERGY);const current=Math.max(0,Number(row.energy||0));const last=Number(row.updated_at||now);if(current<=0){const readyAt=last+3600000;if(now>=readyAt)return {energy:max,max,regen:0,ticks:0,anchor:now,nextRegenAt:0};return {energy:0,max,regen:0,ticks:0,anchor:last,nextRegenAt:readyAt};}return {energy:Math.min(max,current),max,regen:0,ticks:0,anchor:last,nextRegenAt:0}}
function rankFromPoints(p){return p>=300000?'Grandmaster':p>=150000?'Master':p>=75000?'Diamond':p>=35000?'Platinum':p>=15000?'Gold':p>=5000?'Silver':p>=1000?'Bronze':'Rookie';}
