async function refreshed(env,row){const now=Date.now();const e=energyState(row,now);await env.DB.prepare('UPDATE users SET energy=?,updated_at=? WHERE telegram_id=?').bind(e.energy,e.anchor,row.telegram_id).run();const updated=await getUser(env,row.telegram_id);const refs=await env.DB.prepare('SELECT COUNT(*) AS n FROM referrals WHERE inviter_id=?').bind(row.telegram_id).first();const today=indiaDay(now);const daily=await env.DB.prepare('SELECT id FROM daily_claims WHERE telegram_id=? AND claim_day=? LIMIT 1').bind(row.telegram_id,today).first();await env.DB.prepare('CREATE TABLE IF NOT EXISTS task_claims_v2 (telegram_id TEXT NOT NULL, task TEXT NOT NULL, claim_day TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(telegram_id,task,claim_day))').run();const taskRows=await env.DB.prepare('SELECT task FROM task_claims_v2 WHERE telegram_id=? AND claim_day=?').bind(row.telegram_id,today).all();const taskStatus={};for(const x of (taskRows.results||[]))taskStatus[String(x.task)]=true;const lastDaily=await env.DB.prepare('SELECT created_at FROM daily_claims WHERE telegram_id=? ORDER BY created_at DESC LIMIT 1').bind(row.telegram_id).first();const lastDailyAt=Number(lastDaily?.created_at||0);const nextDailyAt=lastDailyAt?lastDailyAt+86400000:0;const shaped=userShape(updated,Number(refs?.n||0),taskStatus);shaped.lastDailyClaimed=!!(nextDailyAt&&now<nextDailyAt);shaped.lastDailyClaimAt=lastDailyAt;shaped.nextDailyAt=nextDailyAt;shaped.nextEnergyAt=e.nextRegenAt;shaped.regenPerTick=e.regen;shaped.energyCost=Math.max(1,Math.min(100,Number(await readAdminSetting(env,'energy_cost','10'))||10));return shaped}
